function wrapT(t, n) { const w = t.split(' '), L = []; let c = ''; w.forEach(x => { if ((c + ' ' + x).trim().length > n) { L.push(c.trim()); c = x; } else c += ' ' + x; }); if (c.trim()) L.push(c.trim()); return L; }
const CP = { pop: '#E0663A', opt: '#23845D', pomp: '#2F7FB8', ces: '#C8373A', tri: '#7F77DD', par: '#8E6FB8', gal: '#2F6A9E' };
