function faceM(id, key, x, y, r, col, d) { return `<g class="pop" style="animation-delay:${d}s"><circle cx="${x}" cy="${y}" r="${f1(r + 4)}" fill="${col}"/><circle cx="${x}" cy="${y}" r="${f1(r + 1.2)}" fill="#FBF6EA"/><use href="#fg-face-${key}" transform="translate(${f1(x - r)} ${f1(y - r)}) scale(${f1(2 * r / 180 * 1000) / 1000})" clip-path="url(#${id})"/></g>`; }
