function fireBank(x0, x1, base, hMax, n, seed, o = {}) {
  let a = seed * 9301 + 49297; const rnd = () => { a = (a * 9301 + 49297) % 233280; return a / 233280; };
  const env = o.env || (t => 1 - Math.pow(Math.abs(t - .5) * 2, 2) * .55);
  const tongue = (fx, w, h, lean) => `M${f1(fx - w / 2)} ${f1(base)} C${f1(fx - w * .6)} ${f1(base - h * .32)} ${f1(fx - w * .22 + lean * h * .25)} ${f1(base - h * .58)} ${f1(fx - w * .05 + lean * h * .45)} ${f1(base - h * .8)} C${f1(fx + lean * h * .55)} ${f1(base - h * .9)} ${f1(fx + lean * h * .62)} ${f1(base - h * .96)} ${f1(fx + lean * h * .58)} ${f1(base - h)} C${f1(fx + w * .18 + lean * h * .35)} ${f1(base - h * .74)} ${f1(fx + w * .62)} ${f1(base - h * .42)} ${f1(fx + w / 2)} ${f1(base)} Z`;
  const layers = [['#A8200C', .95, 1.0, 'fa', 1.0], ['#E8561A', .95, .82, 'fb', .9], ['#FF9A2A', 1, .62, 'fb', .8], ['#FFD45A', 1, .42, 'fc', .7], ['#FFF3C0', .95, .22, 'fc', .5]];
  let out = `<g>`;
  if (!o.noglow) out += `<ellipse class="flick2" cx="${f1((x0 + x1) / 2)}" cy="${f1(base - hMax * .3)}" rx="${f1((x1 - x0) * .6)}" ry="${f1(hMax * .5)}" fill="#FF7A2A" opacity=".16" filter="url(#fgFireBlur)"/>`;
  layers.forEach(([col, op, hs, cls, ws], li) => {
    const m = Math.max(2, Math.round(n * (1 - li * .12)));
    let g = '';
    for (let i = 0; i < m; i++) {
      const t = (i + .5 + (rnd() - .5) * .6) / m, fx = x0 + t * (x1 - x0), w = (x1 - x0) / m * (1.5 + rnd() * .8) * ws, h = hMax * hs * env(t) * (.72 + rnd() * .4), lean = (rnd() - .5) * .5;
      g += `<path class="${cls}" style="transform-origin:${f1(fx)}px ${f1(base)}px;animation-delay:-${(rnd() * 1.2).toFixed(2)}s;animation-duration:${(.45 + rnd() * .6).toFixed(2)}s" d="${tongue(fx, w, h, lean)}" fill="${col}" opacity="${op}"/>`;
      if (li === 1 && rnd() < .55) { const lh = h * .22, lx = fx + lean * h * .58; g += `<path class="lick" style="animation-delay:${(rnd() * 1.4).toFixed(2)}s;animation-duration:${(.8 + rnd() * .6).toFixed(2)}s" d="M${f1(lx - lh * .2)} ${f1(base - h * .92)} C${f1(lx - lh * .25)} ${f1(base - h * .92 - lh * .6)} ${f1(lx)} ${f1(base - h * .92 - lh)} ${f1(lx + lh * .05)} ${f1(base - h * .92 - lh * 1.1)} C${f1(lx + lh * .2)} ${f1(base - h * .92 - lh * .6)} ${f1(lx + lh * .25)} ${f1(base - h * .92 - lh * .3)} ${f1(lx + lh * .2)} ${f1(base - h * .92)} Z" fill="#F2711C"/>`; }
    }
    out += li === 0 ? `<g filter="url(#fgFireSoft)">${g}</g>` : `<g>${g}</g>`;
  });
  return out + '</g>';
}
