function shiftSvg(svg, off) {
  return svg.replace(/animation-delay:(-?[\d.]+)s/g, (m, x) => `animation-delay:${(+x + off).toFixed(2)}s`).replace(/animation:(fgcam\w+) ([\d.]+)s ease-in-out both/g, (m, n, d) => `animation:${n} ${d}s ease-in-out ${off}s both`);
}
function buildViz() {
  const O = buildVizOld();
  const N = [
    { svg: chartSulla(), cap: 'Silla aggiunge al Senato circa 300 cavalieri (Appiano, Guerre civili I 100) e rende automatico l\'ingresso dei questori, portati a 20 l\'anno. I valori sono arrotondati.', leg: [] },
    { svg: chartCensors(), cap: 'I censori del 70 a.C., Lucio Gellio Publicola e Gneo Cornelio Lentulo Clodiano, cancellano 64 nomi dall\'albo del Senato (epitome di Livio 98). Ogni tratto è un senatore; quali siano quelli cancellati è puramente illustrativo.', leg: [] },
    { svg: chartDebate(), cap: 'Il pallino indica solo l\'orientamento dell\'aula secondo i racconti di Sallustio e Plutarco: i voti non furono contati.', leg: [] },
    { svg: chartTriumv(), cap: 'Un patto privato, senza base legale: ciascuno dei tre ottiene ciò che il Senato gli negava.', leg: [] },
    { svg: mapGallia(), cap: '58–51 a.C. Le campagne di Cesare anno per anno, fino alla resa di Vercingetorige ad Alesia (52). «La Gallia è divisa in tre parti»: Belgi, Aquitani e Celti, che i Romani chiamano Galli; la Garonna li separa dagli Aquitani, la Senna e la Marna dai Belgi (Cesare, La guerra gallica I 1). Ad Atuatuca (54) viene distrutta una legione e mezza; a Gergovia (52) Cesare è respinto. Luoghi di Ariovisto, del Sabis e di Atuatuca discussi; percorsi schematici.', leg: [[CP.ces, 'Cesare'], ['#2F6A9E', 'Belgi'], ['#D99A12', 'Aquitani']] },
    { svg: mapCarre(), cap: 'Giugno 53 a.C. Crasso invade il regno dei Parti e viene sconfitto presso Carre. La morte di Giulia (54) e quella di Crasso lasciano soli Cesare e Pompeo.', leg: [[CP.tri, 'Crasso'], [CP.par, 'Parti']] },
    { svg: sceneCuria(), cap: 'Ricostruzione simbolica dei fatti del 52 a.C., secondo Asconio (commento alla Pro Milone): lo scontro sulla via Appia presso Boville, il rogo del corpo di Clodio nella Curia Ostilia, che brucia con la Basilica Porcia, e la nomina di Pompeo a console senza collega. Sarà Cesare a far costruire la nuova sede, la Curia Iulia.', leg: [] },
    O[0],
    { svg: mapCivA(), cap: '49–48 a.C. Cesare entra in Italia, Pompeo e buona parte del Senato passano in Grecia. Dopo lo scacco di Durazzo, Cesare vince a Farsalo; Pompeo fugge in Egitto e viene ucciso.', leg: [[CP.ces, 'Cesare'], [CP.pomp, 'Pompeo']] },
    { svg: sceneCleopatra(), cap: 'Ricostruzione simbolica. Secondo Plutarco (Cesare 49) Cleopatra, esclusa dal trono dal fratello Tolomeo XIII, si fece portare nel palazzo dentro un sacco di coperte; la leggenda del tappeto è moderna. Dopo la guerra di Alessandria Cesare risalì il Nilo con lei (Svetonio, Cesare 52); il figlio Tolomeo Cesare, detto Cesarione, nacque nel 47.', leg: [] },
    { svg: mapCivB(), cap: '46–45 a.C. Le ultime resistenze dei pompeiani, alleati del re numida Giuba, cadono a Tapso, in Africa, e a Munda, in Spagna: le loro aree passano a Cesare, che annette la Numidia come Africa Nova.', leg: [[CP.ces, 'Cesare'], [CP.opt, 'Repubblicani']] },
    { svg: sceneDictator(), cap: 'Denario di Cesare del 44 a.C., coniato nelle settimane prima delle Idi: testa laureata e legenda CAESAR DICT PERPETVO. È la prima volta che un Romano vivente compare su una moneta.', leg: [] },
    O[2], O[3]
  ];
  const V = N.concat(O.slice(4));
  { const g0 = V[22].svg, AT = 6.2, AD = 10.2; V[22] = { svg: `<g class="act" style="animation-delay:0s;animation-duration:${AT + .3}s">${g0}</g><g class="act" style="animation-delay:${AT}s;animation-duration:${AD + .3}s">${shiftSvg(sceneCleoDeath(), AT)}</g><g class="act last" style="animation-delay:${AT + AD}s">${shiftSvg(g0, AD)}</g>`, cap: V[22].cap + ' La scena della morte segue Plutarco (Antonio 85–86): il cesto di fichi, il letto d\'oro, le ancelle Iras e Carmione; lo stesso Plutarco riferisce anche altre versioni, come il veleno nascosto in un pettine.', leg: V[22].leg }; }
  { const g0 = V[4].svg, AT = 17.2, AD = 19.2; V[4] = { svg: `<g class="act" style="animation-delay:0s;animation-duration:${AT + .3}s">${g0}</g><g class="act" style="animation-delay:${AT}s;animation-duration:${AD + .3}s">${shiftSvg(sceneAlesia(), AT)}</g><g class="act last" style="animation-delay:${AT + AD}s">${shiftSvg(g0, AD)}</g>`, cap: V[4].cap + ' Ad Alesia (settembre 52) la contravallazione misurava circa 11 miglia romane e la circonvallazione 14, cioè 16 e 21 km (Cesare, La guerra gallica VII 69–89); la resa di Vercingetorige è raccontata da Plutarco, Cesare 27.', leg: V[4].leg }; }
  V[8] = { svg: `<g class="act" style="animation-delay:0s;animation-duration:8.2s">${sceneRubicon()}</g><g class="act last" style="animation-delay:7.9s">${shiftSvg(V[8].svg, 8.1)}</g>`, cap: 'Nella notte tra il 10 e l\'11 gennaio 49 a.C. Cesare passa con la XIII legione il Rubicone, confine tra la sua provincia e l\'Italia, dove un governatore non poteva entrare in armi. «Il dado è tratto» è la frase riportata da Svetonio (Cesare 32); secondo Plutarco la pronunciò in greco, citando il commediografo Menandro. Poi la mappa: Pompeo e metà del Senato lasciano l\'Italia, Cesare vince a Farsalo, Pompeo viene ucciso in Egitto.', leg: V[8].leg };
  V[14] = { svg: `<g class="act" style="animation-delay:0s;animation-duration:8.9s">${sceneFuneral()}</g><g class="act last" style="animation-delay:8.6s">${shiftSvg(V[14].svg, 8.8)}</g>`, cap: 'Il 20 marzo 44 a.C. Antonio pronuncia l\'elogio funebre di Cesare, legge il testamento, che lascia 300 sesterzi a ogni cittadino, e mostra la toga insanguinata; la folla brucia il corpo nel Foro e assale le case dei congiurati (Appiano, Guerre civili II 143–148; Plutarco, Bruto 20). Poi la mappa: nei mesi successivi Ottaviano sbarca in Puglia e raggiunge Roma, mentre Bruto e Cassio partono per l\'Oriente.', leg: V[14].leg };
  V[16] = { svg: chartTriumv2(), cap: 'Novembre 43 a.C. Dopo l\'incontro presso Bononia, la lex Titia fa di Antonio, Ottaviano e Lepido i «triumviri per rifondare lo Stato» per cinque anni e divide tra loro le province d\'Occidente (Appiano IV 2–3; Cassio Dione XLVI 55).', leg: [] };
  return V;
}
